  1	#!/usr/bin/env node
  2	// Unified entry point for the Codex CLI.
  3	
  4	import { spawn } from "node:child_process";
  5	import { existsSync, readFileSync, realpathSync } from "fs";
  6	import { createRequire } from "node:module";
  7	import path from "path";
  8	import { fileURLToPath } from "url";
  9	
 10	// __dirname equivalent in ESM
 11	const __filename = fileURLToPath(import.meta.url);
 12	const __dirname = path.dirname(__filename);
 13	const require = createRequire(import.meta.url);
 14	const codexPackageRoot = realpathSync(path.join(__dirname, ".."));
 15	
 16	const PLATFORM_PACKAGE_BY_TARGET = {
 17	  "x86_64-unknown-linux-musl": "@openai/codex-linux-x64",
 18	  "aarch64-unknown-linux-musl": "@openai/codex-linux-arm64",
 19	  "x86_64-apple-darwin": "@openai/codex-darwin-x64",
 20	  "aarch64-apple-darwin": "@openai/codex-darwin-arm64",
 21	  "x86_64-pc-windows-msvc": "@openai/codex-win32-x64",
 22	  "aarch64-pc-windows-msvc": "@openai/codex-win32-arm64",
 23	};
 24	
 25	const { platform, arch } = process;
 26	
 27	let targetTriple = null;
 28	switch (platform) {
 29	  case "linux":
 30	  case "android":
 31	    switch (arch) {
 32	      case "x64":
 33	        targetTriple = "x86_64-unknown-linux-musl";
 34	        break;
 35	      case "arm64":
 36	        targetTriple = "aarch64-unknown-linux-musl";
 37	        break;
 38	      default:
 39	        break;
 40	    }
 41	    break;
 42	  case "darwin":
 43	    switch (arch) {
 44	      case "x64":
 45	        targetTriple = "x86_64-apple-darwin";
 46	        break;
 47	      case "arm64":
 48	        targetTriple = "aarch64-apple-darwin";
 49	        break;
 50	      default:
 51	        break;
 52	    }
 53	    break;
 54	  case "win32":
 55	    switch (arch) {
 56	      case "x64":
 57	        targetTriple = "x86_64-pc-windows-msvc";
 58	        break;
 59	      case "arm64":
 60	        targetTriple = "aarch64-pc-windows-msvc";
 61	        break;
 62	      default:
 63	        break;
 64	    }
 65	    break;
 66	  default:
 67	    break;
 68	}
 69	
 70	if (!targetTriple) {
 71	  throw new Error(`Unsupported platform: ${platform} (${arch})`);
 72	}
 73	
 74	const platformPackage = PLATFORM_PACKAGE_BY_TARGET[targetTriple];
 75	if (!platformPackage) {
 76	  throw new Error(`Unsupported target triple: ${targetTriple}`);
 77	}
 78	
 79	function findCodexExecutable() {
 80	  let vendorRoot;
 81	  try {
 82	    const packageJsonPath = require.resolve(`${platformPackage}/package.json`);
 83	    vendorRoot = path.join(path.dirname(packageJsonPath), "vendor");
 84	  } catch {
 85	    vendorRoot = path.join(__dirname, "..", "vendor");
 86	  }
 87	
 88	  const codexExecutable = path.join(
 89	    vendorRoot,
 90	    targetTriple,
 91	    "bin",
 92	    process.platform === "win32" ? "codex.exe" : "codex",
 93	  );
 94	  if (existsSync(codexExecutable)) {
 95	    return codexExecutable;
 96	  }
 97	
 98	  const packageManager = detectPackageManager();
 99	  const updateCommand =
100	    packageManager === "bun"
101	      ? "bun install -g @openai/codex@latest"
102	      : packageManager === "pnpm"
103	        ? "pnpm add -g @openai/codex@latest"
104	        : packageManager === "vite-plus"
105	          ? "vp install -g @openai/codex@latest"
106	          : "npm install -g @openai/codex@latest";
107	  throw new Error(
108	    `Missing optional dependency ${platformPackage}. Reinstall Codex: ${updateCommand}`,
109	  );
110	}
111	
112	const binaryPath = findCodexExecutable();
113	
114	// Use an asynchronous spawn instead of spawnSync so that Node is able to
115	// respond to signals (e.g. Ctrl-C / SIGINT) while the native binary is
116	// executing. This allows us to forward those signals to the child process
117	// and guarantees that when either the child terminates or the parent
118	// receives a fatal signal, both processes exit in a predictable manner.
119	
120	function isPnpmOwnedCodexInstall(nodeModulesDir) {
121	  if (!existsSync(path.join(nodeModulesDir, ".modules.yaml"))) {
122	    return false;
123	  }
124	
125	  try {
126	    return (
127	      realpathSync(path.join(nodeModulesDir, "@openai", "codex")) ===
128	      codexPackageRoot
129	    );
130	  } catch {
131	    return false;
132	  }
133	}
134	
135	function isVitePlusOwnedCodexInstall(packagesDir) {
136	  if (path.basename(packagesDir) !== "packages") {
137	    return false;
138	  }
139	
140	  try {
141	    const metadata = JSON.parse(
142	      readFileSync(path.join(packagesDir, "@openai", "codex.json"), "utf8"),
143	    );
144	    if (metadata.name !== "@openai/codex") {
145	      return false;
146	    }
147	
148	    // Vite+ records the active global installation in packages/@openai/codex.json.
149	    // Older installs have no ID or append a #-prefixed ID to the package name;
150	    // newer installs put the ID in a subdirectory of the package prefix.
151	    const installId = metadata.installId || "";
152	    const installDir = installId.startsWith("#")
153	      ? path.join(packagesDir, `@openai/codex${installId}`)
154	      : path.join(packagesDir, "@openai/codex", installId);
155	    for (const nodeModulesDir of [
156	      path.join(installDir, "lib", "node_modules"),
157	      path.join(installDir, "node_modules"),
158	    ]) {
159	      const packageRoot = path.join(nodeModulesDir, "@openai", "codex");
160	      if (
161	        existsSync(packageRoot) &&
162	        realpathSync(packageRoot) === codexPackageRoot
163	      ) {
164	        return true;
165	      }
166	    }
167	  } catch {
168	    // Missing or unreadable ownership metadata must not prevent Codex starting.
169	  }
170	  return false;
171	}
172	
173	/**
174	 * Use heuristics to detect the package manager that was used to install Codex
175	 * in order to give the user a hint about how to update it.
176	 */
177	function detectPackageManager() {
178	  // Package-manager ownership metadata can be several parents above the package.
179	  // Search ancestors of both the canonical package root and lexical entrypoint
180	  // because the package manager may link either path.
181	  const entrypointDir = path.dirname(path.resolve(process.argv[1]));
182	  for (const startDir of new Set([codexPackageRoot, entrypointDir])) {
183	    const filesystemRoot = path.parse(startDir).root;
184	    for (
185	      let currentDir = startDir;
186	      currentDir !== filesystemRoot;
187	      currentDir = path.dirname(currentDir)
188	    ) {
189	      if (isVitePlusOwnedCodexInstall(currentDir)) {
190	        return "vite-plus";
191	      }
192	      if (isPnpmOwnedCodexInstall(path.join(currentDir, "node_modules"))) {
193	        return "pnpm";
194	      }
195	    }
196	
197	    if (isPnpmOwnedCodexInstall(path.join(filesystemRoot, "node_modules"))) {
198	      return "pnpm";
199	    }
200	  }
201	
202	  const userAgent = process.env.npm_config_user_agent || "";
203	  if (/\bbun\//.test(userAgent)) {
204	    return "bun";
205	  }
206	
207	  const execPath = process.env.npm_execpath || "";
208	  if (execPath.includes("bun")) {
209	    return "bun";
210	  }
211	
212	  if (
213	    __dirname.includes(".bun/install/global") ||
214	    __dirname.includes(".bun\\install\\global")
215	  ) {
216	    return "bun";
217	  }
218	
219	  return userAgent ? "npm" : null;
220	}

